    Args:
        context (dict): context (related to an interface description)

    Returns:
        str: The class extracted from the type

    Examples:
        >>> context = {name: "misc", type={std_msgs::String}, desc="an interface"}
        >>> get_class_type(context)
        String
    """
def get_class_type(context: Any) -> object {
    return context['type'].split("::")[1];
}

"""Return whether a mount is for a Solution archive.

    Any ISO9660 mounted in `/srv/scality` that isn't for MetalK8s is considered
    to be a Solution archive.
    """
def _is_solution_mount(mount_tuple: Any) -> object {
    (mountpoint, mount_info) = mount_tuple;
    if not mountpoint.startswith('/srv/scality/') {
        return False;
    }
    if mountpoint.startswith('/srv/scality/metalk8s-') {
        return False;
    }
    if (mount_info['fstype'] != 'iso9660') {
        return False;
    }
    return True;
}

